def jaro(s1, s2):
    if s1 == s2: return 1.0
    len1, len2 = len(s1), len(s2)
    if not len1 or not len2: return 0.0
    md = max(0, max(len1, len2)//2 - 1)
    m1 = [False]*len1; m2 = [False]*len2; matches = 0
    for i,c in enumerate(s1):
        for j in range(max(0, i-md), min(len2, i+md+1)):
            if not m2[j] and c == s2[j]:
                m1[i]=True; m2[j]=True; matches+=1; break
    if not matches: return 0.0
    t=0; k=0
    for i in range(len1):
        if m1[i]:
            while not m2[k]: k+=1
            if s1[i]!=s2[k]: t+=1
            k+=1
    t//=2
    return (matches/len1 + matches/len2 + (matches-t)/matches)/3
def jw(s1,s2):
    j=jaro(s1,s2)
    p=0
    for a,b in zip(s1,s2):
        if a==b and p<4: p+=1
        else: break
    return j + p*0.1*(1-j)
cands=['no-headers','number','tsv','delimiter','style','padding','indent','sniff','header-align','body-align','disable-pager','help','version']
cases=[('badflag','disable-pager'),('styel','style'),('styl','style'),('num','number'),('numbers','number'),('header','no-headers'),('headers','no-headers'),('no-header','no-headers'),('pad','padding'),('indent2','indent'),('tsv2','tsv'),('delim','delimiter'),('body','body-align'),('help2','help'),('versio','version'),('xyzzy',None)]
def run(metric, prefix, thresh):
    bad=[]
    for v, expect in cases:
        vv = '--'+v if prefix else v
        cc = ['--'+c for c in cands] if prefix else cands
        scored=sorted(((metric(vv,c),c) for c in cc), key=lambda x:-x[0])
        best=scored[0]
        got = best[1].lstrip('-') if best[0]>thresh else None
        if got!=expect: bad.append((v,got,expect,round(best[0],3)))
    return bad
for mname,m in [('jaro',jaro),('jw',jw)]:
    for prefix in (False,True):
        for th in (0.7,0.8):
            b=run(m,prefix,th)
            print(mname,'prefix' if prefix else 'noprefix','th',th,'->', 'ALL OK' if not b else b)
